// src/generated/vault.ts
var VAULT = "";

// src/ui/dom.ts
function $(id) {
  const el = document.getElementById(id);
  if (!el)
    throw new Error(
      `Element mit ID "${id}" nicht gefunden \u2014 index.html und src/ui sind nicht synchron.`
    );
  return el;
}

// src/ui/auth-ui.ts
var currentHandler = null;
function showLogin(onLogin) {
  currentHandler = onLogin;
  const overlay = $("login-overlay");
  const input = $("login-password");
  const form = $("login-form");
  const error = $("login-error");
  form.onsubmit = (e) => {
    e.preventDefault();
    const value = input.value;
    if (!value) return;
    input.disabled = true;
    error.style.display = "none";
    setTimeout(() => {
      currentHandler?.(value);
      input.disabled = false;
    }, 30);
  };
  overlay.style.display = "flex";
  input.value = "";
  input.focus();
}
function hideLogin() {
  $("login-overlay").style.display = "none";
  currentHandler = null;
}
function reportLoginError(message) {
  const input = $("login-password");
  const error = $("login-error");
  error.textContent = message;
  error.style.display = "block";
  input.value = "";
  input.disabled = false;
  input.focus();
}

// src/ui/splash.ts
function initSplash() {
  const splash = $("splash-screen");
  document.body.classList.add("splash-active");
  function dismiss() {
    splash.classList.add("hidden");
    document.body.classList.remove("splash-active");
    splash.removeEventListener("click", dismiss);
  }
  splash.addEventListener("click", dismiss);
}

// src/auth.ts
var PBKDF2_ITERATIONS = 21e4;
var SALT_BYTES = 16;
var IV_BYTES = 12;
var SESSION_KEY = "barcode-vault-key";
function b64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
function bytesToB64(bytes) {
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
}
async function deriveKey(password, salt) {
  const baseKey = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(password),
    "PBKDF2",
    false,
    ["deriveKey"]
  );
  return crypto.subtle.deriveKey(
    { name: "PBKDF2", salt, iterations: PBKDF2_ITERATIONS, hash: "SHA-256" },
    baseKey,
    { name: "AES-GCM", length: 256 },
    true,
    // extractable: Schlüsselrohbytes werden (statt des Passworts) in sessionStorage gelegt
    ["encrypt", "decrypt"]
  );
}
async function decryptVault(key) {
  const data = b64ToBytes(VAULT);
  const iv = data.slice(SALT_BYTES, SALT_BYTES + IV_BYTES);
  const ciphertext = data.slice(SALT_BYTES + IV_BYTES);
  const plain = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv },
    key,
    ciphertext
  );
  return new TextDecoder().decode(plain);
}
function runApp(plaintext) {
  const run = new Function(plaintext);
  run();
}
async function startWithKeyBytes(keyBytes) {
  try {
    const key = await crypto.subtle.importKey("raw", keyBytes, "AES-GCM", false, [
      "decrypt"
    ]);
    const plaintext = await decryptVault(key);
    runApp(plaintext);
    hideLogin();
    return true;
  } catch {
    sessionStorage.removeItem(SESSION_KEY);
    return false;
  }
}
async function handleLogin(password) {
  const data = b64ToBytes(VAULT);
  const salt = data.slice(0, SALT_BYTES);
  try {
    const key = await deriveKey(password, salt);
    const plaintext = await decryptVault(key);
    const raw = await crypto.subtle.exportKey("raw", key);
    sessionStorage.setItem(SESSION_KEY, bytesToB64(new Uint8Array(raw)));
    runApp(plaintext);
    hideLogin();
  } catch {
    reportLoginError("Falsches Passwort. Bitte erneut versuchen.");
  }
}
async function boot() {
  initSplash();
  const sessionB64 = sessionStorage.getItem(SESSION_KEY);
  if (sessionB64) {
    const ok = await startWithKeyBytes(b64ToBytes(sessionB64));
    if (ok) return;
  }
  showLogin(handleLogin);
}
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", boot);
} else {
  void boot();
}
